<node TEXT="基于Redis实现分布式锁初级版本" ID="ID_1352512817" CREATED="1779869338660" MODIFIED="1779869347473">
<node TEXT="实现" ID="ID_1590103984" CREATED="1779873615536" MODIFIED="1779873618205">
<node STYLE_REF="my_style" ID="ID_399070045" CREATED="1779873650442" MODIFIED="1779873674209"><richcontent TYPE="NODE">

<html>
  <head>
    
  </head>
  <body>
    <div style="background-color: #1e1f22; color: #bcbec4">
      <pre style="font-family: JetBrains Mono,monospace; font-size: 9.0pt"><span style="color: #cf8e6d;">package </span>com.hmdp.utils;<br/><br/><span style="color: #cf8e6d;">import </span>org.springframework.data.redis.core.StringRedisTemplate;<br/><br/><span style="color: #cf8e6d;">import </span>java.util.concurrent.TimeUnit;<br/><br/><span style="color: #cf8e6d;">public class </span>SimpleRedisLock <span style="color: #cf8e6d;">implements </span>ILock{<br/><br/>    <span style="color: #2ead11;">// </span><span style="color: #2ead11; font-family: Microsoft YaHei;">为什么这里不用</span><span style="color: #2ead11;"> @Resource?</span><br style="color: #2ead11;"/><span style="color: #2ead11;">    </span><span style="color: #cf8e6d;">private </span>StringRedisTemplate <span style="color: #c77dbb;">stringRedisTemplate</span>;<br/><br/>    <span style="color: #2ead11;">// name of the lock</span><br style="color: #2ead11;"/><span style="color: #2ead11;">    </span><span style="color: #cf8e6d;">private </span>String <span style="color: #c77dbb;">name</span>;<br/><br/>    <span style="color: #cf8e6d;">public static final </span>String <span style="color: #c77dbb; font-style: italic;">KEY_PREFIX </span>= <span style="color: #6aab73;">&quot;lock:&quot;</span>;<br/><br/>    <span style="color: #cf8e6d;">public </span><span style="color: #56a8f5;">SimpleRedisLock</span>(StringRedisTemplate stringRedisTemplate, String name) {<br/>        <span style="color: #cf8e6d;">this</span>.<span style="color: #c77dbb;">stringRedisTemplate </span>= stringRedisTemplate;<br/>        <span style="color: #cf8e6d;">this</span>.<span style="color: #c77dbb;">name </span>= name;<br/>    }<br/><br/>    <span style="color: #b3ae60;">@Override</span><br style="color: #b3ae60;"/><span style="color: #b3ae60;">    </span><span style="color: #cf8e6d;">public boolean </span><span style="color: #56a8f5;">tryLock</span>(<span style="color: #cf8e6d;">long </span>timeoutSec) {<br/><br/>        <span style="color: #2ead11;">// </span><span style="color: #2ead11; font-family: Microsoft YaHei;">获取当前线程标识</span><br style="color: #2ead11; font-family: Microsoft YaHei;"/><span style="color: #2ead11; font-family: Microsoft YaHei;">        </span><span style="color: #cf8e6d;">long </span>threadId = Thread.<span style="font-style: italic;">currentThread</span>().getId();<br/><br/>        Boolean success = <span style="color: #c77dbb;">stringRedisTemplate</span>.opsForValue().setIfAbsent(<br/>                <span style="color: #c77dbb; font-style: italic;">KEY_PREFIX </span>+ <span style="color: #c77dbb;">name </span>,<br/>                threadId + <span style="color: #6aab73;">&quot;&quot;</span>,<br/>                timeoutSec,<br/>                TimeUnit.<span style="color: #c77dbb; font-style: italic;">SECONDS</span><br style="color: #c77dbb; font-style: italic;"/><span style="color: #c77dbb; font-style: italic;">        </span>);<br/><br/>        <span style="color: #2ead11;">// </span><span style="color: #2ead11; font-family: Microsoft YaHei;">避免空指针风险</span><br style="color: #2ead11; font-family: Microsoft YaHei;"/><span style="color: #2ead11; font-family: Microsoft YaHei;">        </span><span style="color: #cf8e6d;">return </span>Boolean.<span style="color: #c77dbb; font-style: italic;">TRUE</span>.equals(success);<br/>    }<br/><br/>    <span style="color: #b3ae60;">@Override</span><br style="color: #b3ae60;"/><span style="color: #b3ae60;">    </span><span style="color: #cf8e6d;">public void </span><span style="color: #56a8f5;">unlock</span>() {<br/>        <span style="color: #2ead11;">// </span><span style="color: #2ead11; font-family: Microsoft YaHei;">释放锁</span><br style="color: #2ead11; font-family: Microsoft YaHei;"/><span style="color: #2ead11; font-family: Microsoft YaHei;">        </span><span style="color: #c77dbb;">stringRedisTemplate</span>.delete( <span style="color: #c77dbb; font-style: italic;">KEY_PREFIX </span>+ <span style="color: #c77dbb;">name </span>);<br/>    }<br/>}<br/></pre>
    </div>
  </body>
</html>
</richcontent>
